class ChildReconciler {
	constructor() {
		this._childFrame = null;
		this._placeFrame = null;
		this._propFrame = null;
		this._styleFrame = null;
		this._listenerFrame = null;
		this._cloneFrame = null;
		this._contextFrame = null;
		this._siblingFrame = null;
		this._attrFrame = null;
		this._refFrame = null;
	}

	diffChildren(
		parentDom,
		renderResult,
		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
