		let i, j, oldVNode, childVNode, newDom, firstChildDom, refs;

		this._childFrame = newParentVNode;

		let oldChildren = (oldParentVNode && oldParentVNode._children) || EMPTY_ARR;
		let oldChildrenLength = oldChildren.length;

		if (oldDom == EMPTY_OBJ) {
			oldDom = this.resolveInitialOldDom(
				oldParentVNode,
				oldChildrenLength,
				excessDomChildren
			);
		}

		newParentVNode._children = [];
		for (i = 0; i < renderResult.length; i++) {
			childVNode = this.normalizeChild(renderResult[i], newParentVNode, i);

			if (childVNode == null) {
				continue;
			}

			childVNode._parent = newParentVNode;
			childVNode._depth = newParentVNode._depth + 1;

			oldVNode = this.matchOldChild(
				childVNode,
				oldChildren,
				oldChildrenLength,
				i
			);

			oldVNode = oldVNode || EMPTY_OBJ;

			diff(
				parentDom,
				childVNode,
				oldVNode,
				globalContext,
				isSvg,
				excessDomChildren,
				commitQueue,
				oldDom,
				isHydrating
			);

			newDom = childVNode._dom;

			if ((j = childVNode.ref) && oldVNode.ref != j) {
				refs = this.collectRef(refs, oldVNode, childVNode, newDom);
			}

			if (newDom != null) {
				if (firstChildDom == null) {
					firstChildDom = newDom;
				}

				if (this.shouldReorderChild(childVNode, oldVNode)) {
					childVNode._nextDom = oldDom = this.reorderChildren(
						childVNode,
						oldDom,
						parentDom
					);
				} else {
					oldDom = this.placeChild(
						parentDom,
						childVNode,
						oldVNode,
						oldChildren,
						excessDomChildren,
						newDom,
						oldDom
					);
				}

				if (!isHydrating && newParentVNode.type === 'option') {
					parentDom.value = '';
				} else if (typeof newParentVNode.type == 'function') {
					newParentVNode._nextDom = oldDom;
				}
			} else if (
				oldDom &&
				oldVNode._dom == oldDom &&
				oldDom.parentNode != parentDom
			) {
				oldDom = this.getDomSibling(oldVNode);
			}
